/**
 * Dispatches an event whenever the form validity changes.
 */
#checkFormValidity() {
  const completed =
    Boolean(this.#authenticationSelect.value) && this.#form.checkValidity();
  this.dispatchEvent(
    new CustomEvent("config-updated", {
      bubbles: true,
      detail: { completed },
    })
  );
}
